CREATE TABLE capability_assignment_v15(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,capability TEXT NOT NULL CHECK(capability IN('organization.read','organization.write','pii.read','pii.write','access_grant.manage','audit.read','identity.manage','interview.read','interview.write','interview_policy.manage','assessment.request','assessment.read','assessment.input.approve','assessment.publish','note.read','note.write','note.publish','action.read','action.write','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage')),scope_kind TEXT NOT NULL CHECK(scope_kind IN('org','department','employee')),scope_id TEXT NOT NULL,employee_id TEXT,department_id TEXT,PRIMARY KEY(org_id,subject_id,capability,scope_kind,scope_id),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,department_id) REFERENCES org_unit(org_id,id),CHECK((scope_kind='org' AND scope_id=org_id AND employee_id IS NULL AND department_id IS NULL) OR (scope_kind='employee' AND employee_id IS NOT NULL AND scope_id=employee_id AND department_id IS NULL) OR (scope_kind='department' AND department_id IS NOT NULL AND scope_id=department_id AND employee_id IS NULL))) STRICT;
