INSERT INTO access_grant(id,org_id,subject_id,capability,category,scope_kind,scope_id,purpose,valid_from,expires_at,revoked,relation_bound,mfa_required) SELECT '00000000-0000-4000-8000-000000000151',org_id,subject_id,'access_grant.manage','audit','org',org_id,'security_administration',created_at,created_at+3155760000000000,0,0,1 FROM local_bootstrap_receipt WHERE NOT EXISTS(SELECT 1 FROM access_grant g WHERE g.org_id=local_bootstrap_receipt.org_id AND g.subject_id=local_bootstrap_receipt.subject_id AND g.capability='access_grant.manage' AND g.category='audit' AND g.scope_kind='org' AND g.scope_id=local_bootstrap_receipt.org_id AND g.purpose='security_administration' AND g.revoked=0);
INSERT INTO access_grant(id,org_id,subject_id,capability,category,scope_kind,scope_id,purpose,valid_from,expires_at,revoked,relation_bound,mfa_required) SELECT '00000000-0000-4000-8000-000000000152',org_id,subject_id,'audit.read','audit','org',org_id,'security_administration',created_at,created_at+3155760000000000,0,0,1 FROM local_bootstrap_receipt WHERE NOT EXISTS(SELECT 1 FROM access_grant g WHERE g.org_id=local_bootstrap_receipt.org_id AND g.subject_id=local_bootstrap_receipt.subject_id AND g.capability='audit.read' AND g.category='audit' AND g.scope_kind='org' AND g.scope_id=local_bootstrap_receipt.org_id AND g.purpose='security_administration' AND g.revoked=0);
