INSERT INTO delegation_authority(id,org_id,manager_subject_id,capability,category,scope_kind,scope_id,purpose,valid_from,expires_at,mfa_required,approved_by,approved_at,policy_version) SELECT '00000000-0000-4000-8000-000000000154',org_id,subject_id,'audit.read','audit','org',org_id,'security_administration',created_at,created_at+3155760000000000,1,subject_id,created_at,'bootstrap_admin.v1' FROM local_bootstrap_receipt WHERE NOT EXISTS(SELECT 1 FROM delegation_authority a WHERE a.org_id=local_bootstrap_receipt.org_id AND a.manager_subject_id=local_bootstrap_receipt.subject_id AND a.capability='audit.read' AND a.category='audit' AND a.scope_kind='org' AND a.scope_id=local_bootstrap_receipt.org_id AND a.purpose='security_administration' AND a.policy_version='bootstrap_admin.v1');
INSERT INTO delegation_authority(id,org_id,manager_subject_id,capability,category,scope_kind,scope_id,purpose,valid_from,expires_at,mfa_required,approved_by,approved_at,policy_version) SELECT '00000000-0000-4000-8000-000000000155',org_id,subject_id,'identity.manage','audit','org',org_id,'security_administration',created_at,created_at+3155760000000000,1,subject_id,created_at,'bootstrap_admin.v1' FROM local_bootstrap_receipt WHERE NOT EXISTS(SELECT 1 FROM delegation_authority a WHERE a.org_id=local_bootstrap_receipt.org_id AND a.manager_subject_id=local_bootstrap_receipt.subject_id AND a.capability='identity.manage' AND a.category='audit' AND a.scope_kind='org' AND a.scope_id=local_bootstrap_receipt.org_id AND a.purpose='security_administration' AND a.policy_version='bootstrap_admin.v1');
